// Lichess AccuracyPercent.scala: https://github.com/lichess-org/lila/blob/master/modules/analyse/src/main/AccuracyPercent.scala
// White-POV centipawns; mate scores are represented by the engine as large signed cp.
export const ACCURACY_METHOD='lichess-accuracy-v1';
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export const winPercent=cp=>Number.isFinite(cp)?100/(1+Math.exp(-.00368208*clamp(cp,-1000,1000))):null;
export const moveAccuracy=(before,after)=>before==null||after==null?null:after>=before?100:clamp(103.1668100711649*Math.exp(-.04354415386753951*(before-after))-3.166924740191411+1,0,100);
export function gameAccuracy(cps,startColor='w'){const wins=cps.map(winPercent),size=clamp(Math.floor((cps.length-1)/10),2,8),windows=[];for(let i=0;i<Math.min(size,wins.length)-2;i++)windows.push(wins.slice(0,size));for(let i=0;i+size<=wins.length;i++)windows.push(wins.slice(i,i+size));if(!windows.length&&wins.length)windows.push(wins);const weighted={w:[],b:[]};for(let i=0;i<wins.length-1;i++){const values=windows[i];if(!values||values.some(x=>x==null)||wins[i]==null||wins[i+1]==null)continue;const mean=values.reduce((a,b)=>a+b,0)/values.length,weight=clamp(Math.sqrt(values.reduce((s,x)=>s+(x-mean)**2,0)/values.length),.5,12),color=i%2===0?startColor:(startColor==='w'?'b':'w'),a=moveAccuracy(color==='w'?wins[i]:100-wins[i],color==='w'?wins[i+1]:100-wins[i+1]);weighted[color].push({a,weight})}return Object.fromEntries(['w','b'].map(c=>{const v=weighted[c];if(!v.length)return[c,null];const wm=v.reduce((s,x)=>s+x.a*x.weight,0)/v.reduce((s,x)=>s+x.weight,0),hm=v.some(x=>x.a===0)?0:v.length/v.reduce((s,x)=>s+1/x.a,0);return[c,(wm+hm)/2]}))}
export function resultAccuracy(moves,results){return gameAccuracy(Array.from({length:moves.length+1},(_,i)=>Number.isFinite(results[i]?.cp)?results[i].cp:null),moves[0]?.color||'w')}
